package com.syll.domain.challenge

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.fail
import org.junit.Test

/**
 * iOS `MatchMadnessBackendParityTests`: cross-checks the engine against the backend's own `Board` and `replay`
 * (backend `src/modules/challenge/domain/match-madness.ts`). The fixture (`match_madness_parity.json`, copied from the
 * iOS test) was generated by running that code on a level 3 plan (16 occurrences of 12 meanings, so 4 repeats) with
 * one wrong attempt; the backend accepted the events (3 stars). Regenerate it whenever the backend's board rules change.
 */
class MatchMadnessBackendParityTest {
    @Serializable
    private data class Fixture(val plan: ChallengeRunPlan, val steps: List<Step>, val events: List<MatchAttemptEvent>) {
        @Serializable
        data class Step(val words: List<String>, val meanings: List<String>)
    }

    @Test
    fun engineReproducesTheBackendBoardAndEvents() {
        val text = checkNotNull(javaClass.classLoader.getResource("match_madness_parity.json")).readText()
        val fixture = Json { ignoreUnknownKeys = true }.decodeFromString(Fixture.serializer(), text)
        val engine = MatchMadnessEngine(fixture.plan)
        var state = engine.initialState()
        var step = 0
        assertEquals(fixture.steps[0].words, state.wordOrder)
        assertEquals(fixture.steps[0].meanings, state.meaningOrder)

        for (event in fixture.events) {
            state = engine.reduce(state, MatchMadnessAction.TapWord(event.wordTileId, event.elapsedMs)).state
            val result = engine.reduce(state, MatchMadnessAction.TapMeaning(event.meaningTileId, event.elapsedMs))
            state = result.state
            when (result.feedback) {
                is MatchMadnessFeedback.Correct -> {
                    step += 1
                    assertEquals("word column after $step matches", fixture.steps[step].words, state.wordOrder)
                    assertEquals("meaning column after $step matches", fixture.steps[step].meanings, state.meaningOrder)
                }
                MatchMadnessFeedback.GoalReached -> step += 1
                is MatchMadnessFeedback.Wrong ->
                    assertEquals("a wrong pair doesn't reorder", fixture.steps[step].words, state.wordOrder)
                else -> fail("event ${event.seq} used a tile that wasn't on the board")
            }
        }

        assertEquals(fixture.steps.size, step)
        assertEquals(MatchMadnessState.Phase.GOAL_REACHED, state.phase)
        assertEquals(fixture.events, state.events)
        assertEquals(1, state.wrongCount)
        assertEquals(11, state.longestCombo)
        assertEquals("the server's score, clear bonus included", 2520, state.provisionalScore)
        val body = MatchMadnessEngine.commitBody(state, ChallengeEndedReason.GOAL_REACHED, endedElapsedMs = 99_999)
        assertEquals("goal_reached ends exactly at the last event", 21_500, body.endedElapsedMs)
    }
}
